package net.officefloor.hq.app.invoices;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.math.RoundingMode;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.TaxRate;
import net.officefloor.hq.app.Today;
import net.officefloor.hq.app.clients.ClientRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Lists a client's invoices, opens one, starts new drafts, adds lines to them, gives them a discount,
 * sends them and records payments against them.
 */
@Service
public class InvoiceService {

    private final InvoiceRepository invoices;
    private final PaymentRepository payments;
    private final ClientRepository clients;
    private final Today today;
    private final TaxRate taxRate;
    private final Audit audit;

    public InvoiceService(InvoiceRepository invoices, PaymentRepository payments, ClientRepository clients,
            Today today, TaxRate taxRate, Audit audit) {
        this.invoices = invoices;
        this.payments = payments;
        this.clients = clients;
        this.today = today;
        this.taxRate = taxRate;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Invoice> forClient(Long clientId) {
        return invoices.findByClientIdOrderByIdAsc(clientId);
    }

    @Transactional(readOnly = true)
    public Optional<Invoice> find(Long id) {
        return invoices.findWithLinesById(id);
    }

    /** An empty draft for the client, issued today and due on the last day of the following month; empty if no such client. */
    @Transactional
    public Optional<Invoice> newDraft(Long clientId) {
        if (!clients.existsById(clientId)) {
            return Optional.empty();
        }
        LocalDate issued = today.date();
        return Optional.of(invoices.save(Invoice.draft(clientId, issued, dueDateFor(issued))));
    }

    /** A new invoice is due on the last day of the month after the month it is issued in. */
    static LocalDate dueDateFor(LocalDate issued) {
        LocalDate nextMonth = issued.plusMonths(1);
        return nextMonth.withDayOfMonth(nextMonth.lengthOfMonth());
    }

    /**
     * Adds a line to a draft invoice; empty if no such invoice. The line has already been checked;
     * a sent invoice refuses it.
     */
    @Transactional
    public Optional<Invoice> addLine(Long invoiceId, String description, BigDecimal qty, BigDecimal unitPrice,
            boolean taxExempt) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            if (!invoice.isDraft()) {
                throw new InvoiceRejectedException("Only a draft invoice can take new lines.");
            }
            invoice.addLine(new InvoiceLine(description, qty, unitPrice, taxExempt));
            invoices.saveAndFlush(invoice);
        });
        return found;
    }

    /**
     * Gives a draft invoice a percentage discount; empty if no such invoice. The percentage has
     * already been checked; a sent invoice refuses it.
     */
    @Transactional
    public Optional<Invoice> setDiscount(Long invoiceId, BigDecimal discountPct) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            if (!invoice.isDraft()) {
                throw new InvoiceRejectedException("Only a draft invoice can be given a discount.");
            }
            invoice.setDiscountPct(discountPct);
            invoices.saveAndFlush(invoice);
        });
        return found;
    }

    /**
     * Sends a draft invoice, keeping its issue and due dates, and records it in the audit; empty if
     * no such invoice. An invoice already sent, or with no lines, is refused.
     */
    @Transactional
    public Optional<Invoice> send(Long invoiceId) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            if (!invoice.isDraft()) {
                throw new InvoiceRejectedException("This invoice has already been sent.");
            }
            if (invoice.getLines().isEmpty()) {
                throw new InvoiceRejectedException("Add at least one line before sending the invoice.");
            }
            invoice.markSent();
            invoices.saveAndFlush(invoice);
            audit.record("INVOICE_SENT id=" + invoice.getId() + " number=" + InvoiceNumber.of(invoice.getId())
                    + " total=" + invoice.total(taxRate.percent()).toPlainString());
        });
        return found;
    }

    /** The payments made to the invoice, oldest first, with their allocations. */
    @Transactional(readOnly = true)
    public List<Payment> payments(Long invoiceId) {
        return payments.findForInvoice(invoiceId);
    }

    /** What has been paid to each of the invoices; an invoice paid nothing is paid zero. */
    @Transactional(readOnly = true)
    public Map<Long, BigDecimal> paid(List<Invoice> list) {
        Map<Long, BigDecimal> paid = new HashMap<>();
        list.forEach(i -> paid.put(i.getId(), BigDecimal.ZERO.setScale(2)));
        if (!list.isEmpty()) {
            for (Object[] row : payments.paidTo(list.stream().map(Invoice::getId).toList())) {
                paid.put((Long) row[0], ((BigDecimal) row[1]).setScale(2));
            }
        }
        return paid;
    }

    /**
     * Records a payment of the amount on the date against a sent invoice that still has something
     * due, and records it in the audit; empty if no such invoice. The amount has already been
     * checked; a draft, an invoice already paid, or an amount over what is due is refused.
     */
    @Transactional
    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal amount, LocalDate date) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isDraft()) {
                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
            }
            BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
            if (due.signum() <= 0) {
                throw new InvoiceRejectedException("This invoice has already been paid.");
            }
            if (amount.compareTo(due) > 0) {
                throw new InvoiceRejectedException("The payment is more than the $" + due.toPlainString() + " due.");
            }
            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, date));
            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
                    + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
        });
        return found;
    }
}
package net.officefloor.hq.app.invoices;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** An invoice raised for a client, made of lines. */
@Entity
@Table(name = "invoice")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "client_id")
    private Long clientId;

    @Enumerated(EnumType.STRING)
    private InvoiceStatus status;

    @Column(name = "issue_date")
    private LocalDate issueDate;

    @Column(name = "due_date")
    private LocalDate dueDate;

    @Column(name = "discount_pct")
    private BigDecimal discountPct = BigDecimal.ZERO;

    @OneToMany(cascade = CascadeType.ALL)
    @JoinColumn(name = "invoice_id", nullable = false)
    @OrderBy("id")
    private List<InvoiceLine> lines = new ArrayList<>();

    protected Invoice() {
    }

    /** A new, empty draft for a client, issued and due on the given dates. */
    public static Invoice draft(Long clientId, LocalDate issueDate, LocalDate dueDate) {
        Invoice invoice = new Invoice();
        invoice.clientId = clientId;
        invoice.status = InvoiceStatus.DRAFT;
        invoice.issueDate = issueDate;
        invoice.dueDate = dueDate;
        return invoice;
    }

    public Long getId() {
        return id;
    }

    public Long getClientId() {
        return clientId;
    }

    public InvoiceStatus getStatus() {
        return status;
    }

    public LocalDate getIssueDate() {
        return issueDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    /** The percentage taken off the subtotal, 0 to 100 with up to two decimals. */
    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    /** Sets the percentage taken off the subtotal; it has already been checked. */
    public void setDiscountPct(BigDecimal discountPct) {
        this.discountPct = discountPct;
    }

    public List<InvoiceLine> getLines() {
        return lines;
    }

    /** Whether lines can still be added: only a draft is still being written. */
    public boolean isDraft() {
        return status == InvoiceStatus.DRAFT;
    }

    /** Marks the invoice sent; its issue and due dates stay as they are. */
    public void markSent() {
        this.status = InvoiceStatus.SENT;
    }

    /** The status once the given amount has been paid against the grand total at the tax rate. */
    public InvoiceStatus statusWhenPaid(BigDecimal paid, BigDecimal taxRate) {
        if (status != InvoiceStatus.SENT || paid.signum() <= 0) {
            return status;
        }
        return amountDue(paid, taxRate).signum() > 0 ? InvoiceStatus.PART_PAID : InvoiceStatus.PAID;
    }

    /** What is still due once the given amount has been paid: the grand total less it. */
    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
        return total(taxRate).subtract(paid);
    }

    /** Adds a line to the end of the invoice. */
    public void addLine(InvoiceLine line) {
        lines.add(line);
    }

    /**
     * The sum of the line amounts, each already rounded half up to the cent — so the subtotal
     * matches what a client gets by adding up the lines shown.
     */
    public BigDecimal subtotal() {
        return lines.stream().map(InvoiceLine::amount)
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** The amount taken off: the discount percentage of the subtotal, rounded half up to the cent. */
    public BigDecimal discount() {
        return subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100))
                .setScale(2, RoundingMode.HALF_UP);
    }

    /**
     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
     * proportion to the line amounts: each line first gets the whole cents of its exact share
     * (rounded down), then the cents left over go one each to the lines with the largest leftover
     * fractions, equal fractions going to the lower line id. The shares add up to the discount.
     */
    public List<BigDecimal> discountShares() {
        BigInteger discountCents = discount().movePointRight(2).toBigIntegerExact();
        BigInteger subtotalCents = subtotal().movePointRight(2).toBigIntegerExact();
        int n = lines.size();
        BigInteger[] shares = new BigInteger[n];
        BigInteger[] leftovers = new BigInteger[n];
        BigInteger given = BigInteger.ZERO;
        for (int i = 0; i < n; i++) {
            if (subtotalCents.signum() == 0) {
                shares[i] = BigInteger.ZERO;
                leftovers[i] = BigInteger.ZERO;
            } else {
                // The exact share is discount * amount / subtotal; all fractions share the subtotal
                // as denominator, so the remainders compare as the fractions do.
                BigInteger[] qr = discountCents.multiply(lines.get(i).amount().movePointRight(2).toBigIntegerExact())
                        .divideAndRemainder(subtotalCents);
                shares[i] = qr[0];
                leftovers[i] = qr[1];
            }
            given = given.add(shares[i]);
        }
        List<Integer> order = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            order.add(i);
        }
        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
        int left = discountCents.subtract(given).intValueExact();
        for (int k = 0; k < left; k++) {
            int i = order.get(k);
            shares[i] = shares[i].add(BigInteger.ONE);
        }
        List<BigDecimal> result = new ArrayList<>(n);
        for (BigInteger share : shares) {
            result.add(new BigDecimal(share, 2));
        }
        return result;
    }

    /**
     * The tax charged at the given rate (a percentage): each taxable line's amount less its share of
     * the discount, added up, and the rate charged on that, rounded half up to the cent. Tax-exempt
     * lines are left out.
     */
    public BigDecimal tax(BigDecimal taxRate) {
        List<BigDecimal> shares = discountShares();
        BigDecimal taxable = BigDecimal.ZERO;
        for (int i = 0; i < lines.size(); i++) {
            if (!lines.get(i).isTaxExempt()) {
                taxable = taxable.add(lines.get(i).amount().subtract(shares.get(i)));
            }
        }
        return taxable.multiply(taxRate).divide(BigDecimal.valueOf(100))
                .setScale(2, RoundingMode.HALF_UP);
    }

    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
    public BigDecimal total(BigDecimal taxRate) {
        return subtotal().subtract(discount()).add(tax(taxRate));
    }
}
import { Component, effect, inject, input, output, signal } from '@angular/core';
import { HttpErrorResponse } from '@angular/common/http';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { InvoiceDetail, InvoiceService, NewLine, NewPayment } from './invoice.service';
import { money, statusLabel } from './invoice-format';

// A positive decimal with at most two decimals, e.g. 1, 1.5 or 12.35. The server applies the same rules.
const TWO_DECIMALS = /^\d+(\.\d{1,2})?$/;

// A percentage from 0 to 100 with at most two decimals, e.g. 15 or 12.5; the server checks it again.
function problemWithDiscount(pct: string): string {
  if (!pct) {
    return 'Enter a discount percentage.';
  }
  if (!/^-?\d+(\.\d+)?$/.test(pct)) {
    return 'The discount must be a number, like 15 or 12.5.';
  }
  if (Number(pct) < 0 || Number(pct) > 100) {
    return 'The discount must be from 0 to 100 percent.';
  }
  if (!TWO_DECIMALS.test(pct)) {
    return 'The discount can have at most two decimals.';
  }
  return '';
}

// What is wrong with a payment, or '' when it can be recorded.
function problemWithPayment(payment: NewPayment): string {
  const problems: string[] = [];
  if (!payment.amount) {
    problems.push('Enter an amount.');
  } else if (!TWO_DECIMALS.test(payment.amount)) {
    problems.push('The amount must be a number with at most two decimals.');
  } else if (Number(payment.amount) < 0.01) {
    problems.push('The amount must be at least $0.01.');
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(payment.date)) {
    problems.push('Enter the date it was paid.');
  }
  return problems.join(' ');
}

// What is wrong with a line, or '' when it can be added.
function problemWith(line: NewLine): string {
  const problems: string[] = [];
  if (!line.description) {
    problems.push('Enter a description.');
  }
  if (!line.qty) {
    problems.push('Enter a quantity.');
  } else if (!TWO_DECIMALS.test(line.qty)) {
    problems.push('The quantity must be a number with at most two decimals.');
  } else if (Number(line.qty) <= 0) {
    problems.push('The quantity must be more than zero.');
  }
  if (!line.unitPrice) {
    problems.push('Enter a unit price.');
  } else if (!TWO_DECIMALS.test(line.unitPrice)) {
    problems.push('The unit price must be a number with at most two decimals.');
  } else if (Number(line.unitPrice) < 0.01) {
    problems.push('The unit price must be at least $0.01.');
  }
  return problems.join(' ');
}

// One opened invoice: its status, its lines and its totals. A draft takes new lines and a
// percentage discount, and can be sent; once sent, the server refuses further changes. A sent
// invoice takes payments until nothing is due; the panel lists them with what has been paid and
// what is still due.
@Component({
  selector: 'app-invoice-panel',
  imports: [ReactiveFormsModule],
  template: `
    <section data-testid="invoice-panel" aria-labelledby="invoice-panel-heading">
      <h2 id="invoice-panel-heading">
        Invoice <span data-testid="invoice-panel-number">{{ invoice()?.number }}</span>
      </h2>
      @if (invoice(); as inv) {
        <p>Status: <span data-testid="invoice-panel-status">{{ statusLabel(inv.status) }}</span></p>
        <table>
          <thead>
            <tr>
              <th scope="col">Description</th>
              <th scope="col">Qty</th>
              <th scope="col">Unit price</th>
              <th scope="col">Amount</th>
              <th scope="col">Discount share</th>
              <th scope="col">Tax</th>
            </tr>
          </thead>
          <tbody>
            @for (l of inv.lines; track l.id) {
              <tr [attr.data-testid]="'line-row-' + l.id">
                <td data-testid="line-description">{{ l.description }}</td>
                <td data-testid="line-qty">{{ l.qty }}</td>
                <td data-testid="line-unit-price">{{ money(l.unitPrice) }}</td>
                <td data-testid="line-amount">{{ money(l.amount) }}</td>
                <td data-testid="line-discount-share">{{ money(l.discountShare) }}</td>
                <td data-testid="line-tax-exempt">{{ l.taxExempt ? 'Exempt' : 'Taxable' }}</td>
              </tr>
            } @empty {
              <tr>
                <td colspan="6" data-testid="line-empty">No lines yet.</td>
              </tr>
            }
          </tbody>
          <tfoot>
            <tr>
              <th scope="row" colspan="5">Subtotal</th>
              <td data-testid="invoice-subtotal">{{ money(inv.subtotal) }}</td>
            </tr>
            <tr>
              <th scope="row" colspan="5">Discount ({{ inv.discountPct }}%)</th>
              <td data-testid="invoice-discount">{{ money(inv.discount) }}</td>
            </tr>
            <tr>
              <th scope="row" colspan="5">Tax ({{ inv.taxRate }}%)</th>
              <td data-testid="invoice-tax">{{ money(inv.tax) }}</td>
            </tr>
            <tr>
              <th scope="row" colspan="5">Total</th>
              <td data-testid="invoice-grand-total">{{ money(inv.total) }}</td>
            </tr>
          </tfoot>
        </table>

        @if (inv.status !== 'DRAFT') {
          <table aria-label="Payments">
            <thead>
              <tr>
                <th scope="col">Paid on</th>
                <th scope="col">Amount</th>
              </tr>
            </thead>
            <tbody>
              @for (p of inv.payments; track p.id) {
                <tr [attr.data-testid]="'payment-row-' + p.id">
                  <td data-testid="payment-date">{{ p.date }}</td>
                  <td data-testid="payment-amount">{{ money(p.amount) }}</td>
                </tr>
              } @empty {
                <tr>
                  <td colspan="2" data-testid="payment-empty">No payments yet.</td>
                </tr>
              }
            </tbody>
            <tfoot>
              <tr>
                <th scope="row">Paid</th>
                <td data-testid="invoice-paid">{{ money(inv.paid) }}</td>
              </tr>
              <tr>
                <th scope="row">Amount due</th>
                <td data-testid="invoice-amount-due">{{ money(inv.amountDue) }}</td>
              </tr>
            </tfoot>
          </table>
        }

        @if (inv.status === 'SENT' || inv.status === 'PART_PAID') {
          <form
            [formGroup]="paymentForm"
            (ngSubmit)="recordPayment(inv.id)"
            aria-label="Record a payment"
            novalidate
          >
            <label for="payment-amount">Amount ($)</label>
            <input
              id="payment-amount"
              data-testid="payment-form-amount"
              inputmode="decimal"
              formControlName="amount"
              required
            />
            <label for="payment-date">Paid on</label>
            <input
              id="payment-date"
              type="date"
              data-testid="payment-form-date"
              formControlName="date"
              required
            />
            <button type="submit" data-testid="payment-form-submit" [disabled]="savingPayment()">
              Record payment
            </button>
            @if (paymentError()) {
              <p role="alert" data-testid="payment-form-error">{{ paymentError() }}</p>
            }
          </form>
        }

        @if (inv.status === 'DRAFT') {
          <button type="button" data-testid="invoice-send" [disabled]="sending()" (click)="send(inv.id)">
            Send invoice
          </button>
          @if (sendError()) {
            <p role="alert" data-testid="invoice-send-error">{{ sendError() }}</p>
          }
        }

        <form [formGroup]="form" (ngSubmit)="addLine(inv.id)" aria-label="Add a line" novalidate>
          <label for="line-description">Description</label>
          <input
            id="line-description"
            data-testid="line-form-description"
            formControlName="description"
            required
          />
          <label for="line-qty">Quantity</label>
          <input
            id="line-qty"
            data-testid="line-form-qty"
            inputmode="decimal"
            formControlName="qty"
            required
          />
          <label for="line-unit-price">Unit price ($)</label>
          <input
            id="line-unit-price"
            data-testid="line-form-unit-price"
            inputmode="decimal"
            formControlName="unitPrice"
            required
          />
          <input
            id="line-exempt"
            type="checkbox"
            data-testid="line-form-exempt"
            formControlName="taxExempt"
          />
          <label for="line-exempt">Tax exempt</label>
          <button type="submit" data-testid="line-form-submit" [disabled]="saving()">
            Add line
          </button>
          @if (error()) {
            <p role="alert" data-testid="line-form-error">{{ error() }}</p>
          }
        </form>

        <form
          [formGroup]="discountForm"
          (ngSubmit)="setDiscount(inv.id)"
          aria-label="Discount"
          novalidate
        >
          <label for="discount-pct">Discount (%)</label>
          <input
            id="discount-pct"
            data-testid="discount-form-pct"
            inputmode="decimal"
            formControlName="pct"
            required
          />
          <button type="submit" data-testid="discount-form-submit" [disabled]="savingDiscount()">
            Apply discount
          </button>
          @if (discountError()) {
            <p role="alert" data-testid="discount-form-error">{{ discountError() }}</p>
          }
        </form>
      }
    </section>
  `,
})
export class InvoicePanel {
  private readonly service = inject(InvoiceService);

  readonly invoiceId = input.required<number>();
  // The invoice after a change made here, so the list can show its new total.
  readonly changed = output<InvoiceDetail>();

  protected readonly invoice = signal<InvoiceDetail | null>(null);
  protected readonly saving = signal(false);
  protected readonly error = signal('');
  protected readonly savingDiscount = signal(false);
  protected readonly discountError = signal('');
  protected readonly sending = signal(false);
  protected readonly sendError = signal('');
  protected readonly savingPayment = signal(false);
  protected readonly paymentError = signal('');
  protected readonly statusLabel = statusLabel;
  protected readonly money = money;

  protected readonly form = new FormGroup({
    description: new FormControl('', { nonNullable: true }),
    qty: new FormControl('', { nonNullable: true }),
    unitPrice: new FormControl('', { nonNullable: true }),
    taxExempt: new FormControl(false, { nonNullable: true }),
  });

  protected readonly paymentForm = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    date: new FormControl('', { nonNullable: true }),
  });

  protected readonly discountForm = new FormGroup({
    pct: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    effect((onCleanup) => {
      const id = this.invoiceId();
      this.invoice.set(null);
      this.form.reset();
      this.error.set('');
      this.discountForm.reset();
      this.discountError.set('');
      this.sendError.set('');
      this.paymentForm.reset();
      this.paymentError.set('');
      const sub = this.service.open(id).subscribe((detail) => this.invoice.set(detail));
      onCleanup(() => sub.unsubscribe());
    });
  }

  protected addLine(invoiceId: number): void {
    const raw = this.form.getRawValue();
    const line: NewLine = {
      description: raw.description.trim(),
      qty: raw.qty.trim(),
      unitPrice: raw.unitPrice.trim().replace(/^\$/, ''),
      taxExempt: raw.taxExempt,
    };
    const problem = problemWith(line);
    if (problem) {
      this.form.markAllAsTouched();
      this.error.set(problem);
      return;
    }
    this.saving.set(true);
    this.error.set('');
    this.service.addLine(invoiceId, line).subscribe({
      next: (detail) => {
        this.invoice.set(detail);
        this.changed.emit(detail);
        this.form.reset();
        this.saving.set(false);
      },
      error: (e: HttpErrorResponse) => {
        const detail: unknown = e.error?.detail;
        this.error.set(
          typeof detail === 'string' && detail ? detail : 'The line could not be added.',
        );
        this.saving.set(false);
      },
    });
  }

  protected setDiscount(invoiceId: number): void {
    const pct = this.discountForm.getRawValue().pct.trim().replace(/%$/, '').trim();
    const problem = problemWithDiscount(pct);
    if (problem) {
      this.discountForm.markAllAsTouched();
      this.discountError.set(problem);
      return;
    }
    this.savingDiscount.set(true);
    this.discountError.set('');
    this.service.setDiscount(invoiceId, pct).subscribe({
      next: (detail) => {
        this.invoice.set(detail);
        this.changed.emit(detail);
        this.discountForm.reset();
        this.savingDiscount.set(false);
      },
      error: (e: HttpErrorResponse) => {
        const detail: unknown = e.error?.detail;
        this.discountError.set(
          typeof detail === 'string' && detail ? detail : 'The discount could not be applied.',
        );
        this.savingDiscount.set(false);
      },
    });
  }

  protected recordPayment(invoiceId: number): void {
    const raw = this.paymentForm.getRawValue();
    const payment: NewPayment = {
      amount: raw.amount.trim().replace(/^\$/, ''),
      date: raw.date.trim(),
    };
    const problem = problemWithPayment(payment);
    if (problem) {
      this.paymentForm.markAllAsTouched();
      this.paymentError.set(problem);
      return;
    }
    this.savingPayment.set(true);
    this.paymentError.set('');
    this.service.recordPayment(invoiceId, payment).subscribe({
      next: (detail) => {
        this.invoice.set(detail);
        this.changed.emit(detail);
        this.paymentForm.reset();
        this.savingPayment.set(false);
      },
      error: (e: HttpErrorResponse) => {
        const detail: unknown = e.error?.detail;
        this.paymentError.set(
          typeof detail === 'string' && detail ? detail : 'The payment could not be recorded.',
        );
        this.savingPayment.set(false);
      },
    });
  }

  protected send(invoiceId: number): void {
    this.sending.set(true);
    this.sendError.set('');
    this.service.send(invoiceId).subscribe({
      next: (detail) => {
        this.invoice.set(detail);
        this.changed.emit(detail);
        this.sending.set(false);
      },
      error: (e: HttpErrorResponse) => {
        const detail: unknown = e.error?.detail;
        this.sendError.set(
          typeof detail === 'string' && detail ? detail : 'The invoice could not be sent.',
        );
        this.sending.set(false);
      },
    });
  }
}

